create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,role text not null check(role in ('student','parent','admin')),approved boolean not null default false,student_id text unique,class_name text,section text,photo_url text,created_at timestamptz not null default now());
create table if not exists public.parent_children(parent_id uuid references public.profiles(id) on delete cascade,student_id uuid references public.profiles(id) on delete cascade,primary key(parent_id,student_id));
create table if not exists public.attendance(id bigint generated by default as identity primary key,student_id uuid references public.profiles(id) on delete cascade not null,attendance_date date not null,status text check(status in ('present','absent','late')) not null,unique(student_id,attendance_date));
create table if not exists public.exams(id bigint generated by default as identity primary key,name text not null,exam_date date,created_at timestamptz default now());
create table if not exists public.results(id bigint generated by default as identity primary key,student_id uuid references public.profiles(id) on delete cascade not null,exam_id bigint references public.exams(id) on delete cascade not null,subject text not null,obtained numeric not null,total numeric not null,grade text,position integer,published boolean default false);
create table if not exists public.announcements(id bigint generated by default as identity primary key,title text not null,body text not null,published boolean default false,created_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin' and approved=true) $$;
alter table public.profiles enable row level security;alter table public.parent_children enable row level security;alter table public.attendance enable row level security;alter table public.exams enable row level security;alter table public.results enable row level security;alter table public.announcements enable row level security;
create policy "admin profiles" on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "self profile" on public.profiles for select to authenticated using(id=auth.uid() and approved=true);
create policy "admin parent links" on public.parent_children for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin attendance" on public.attendance for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin exams" on public.exams for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin results" on public.results for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin announcements" on public.announcements for all to authenticated using(public.is_admin()) with check(public.is_admin());